import { readFileSync } from 'node:fs'
import { describe, expect, it } from 'vitest'
import {
  flattenChinaTemplateCatalog,
  type ChinaTemplateCatalogNode,
} from '../seeds/chinaGb50300TemplateCatalog.js'
import {
  inferDurationContributionMode,
  isDurationBearingContributionMode,
} from '../seeds/durationContributionMode.js'
import { DOMAIN_WBS_TEMPLATE_CATALOGS } from '../seeds/domainWbsTemplateCatalogs.js'
import { STANDARD_INTERNAL_FLOW_RULE_SEED } from '../seeds/standardInternalFlowSeed.js'
import { STANDARD_WORK_DURATION_SEED } from '../seeds/standardWorkDurationSeed.js'

function flattenNodes(nodes: ChinaTemplateCatalogNode[] = []): ChinaTemplateCatalogNode[] {
  return nodes.flatMap((node) => [node, ...flattenNodes(node.children ?? [])])
}

function templateNodes(templateId: string) {
  const template = DOMAIN_WBS_TEMPLATE_CATALOGS.find((item) => item.templateId === templateId)
  expect(template, `${templateId} should exist`).toBeTruthy()
  return flattenNodes(template!.divisions)
}

function templateNode(templateId: string, stableCode: string) {
  const node = templateNodes(templateId).find((item) => item.stableCode === stableCode)
  expect(node, `${templateId}:${stableCode} should exist`).toBeTruthy()
  return node!
}

function processChildrenFor(templateId: string, stableCode: string) {
  return (templateNode(templateId, stableCode).children ?? [])
    .filter((child) => child.categoryType === 'process')
}

function formalItemWorksFor(templateId: string) {
  return templateNodes(templateId).filter((node) => (
    node.categoryType === 'item_work'
    && !node.stableCode.includes('-90')
    && node.metadata?.coverageSupplement !== true
  ))
}

function fieldDurationProcessChildren(itemWork: ChinaTemplateCatalogNode) {
  return (itemWork.children ?? []).filter((child) => (
    child.categoryType === 'process'
    && child.metadata?.durationContributionMode === 'duration_bearing'
    && child.metadata?.processDepthRole === 'field_duration_work'
  ))
}

function asciiLetterCount(text: string) {
  return text.match(/[A-Za-z]/g)?.length ?? 0
}

function hasChineseFieldText(text: string) {
  return /[\u4e00-\u9fff]/.test(text)
}

