function processNameMatchesFragment(name: string, fragment: string) {
  const candidates = [fragment, ...(LOCALIZED_PROCESS_FRAGMENT_ALIASES[fragment] ?? [])]
  const compactName = name.replace(/\s+/g, '')
  return candidates.some((candidate) => {
    const compactCandidate = candidate.replace(/\s+/g, '')
    return name.includes(candidate) || compactName.includes(compactCandidate)
  })
}

function expectAirportTerminalProcessMetadata(
  stableCode: string,
  itemWork: ChinaTemplateCatalogNode,
  processChildren: ChinaTemplateCatalogNode[],
  expectation: {
    itemWorkName: string
    fieldEvidenceFragments: string[]
    handoverEvidenceType: string
    acceptanceCoreFragment: string
    forbiddenRawFragments: string[]
  },
) {
  const preparationProcess = processChildren[0]!
  const terminalProcess = processChildren.at(-1)!
  const fieldEvidenceKeywords = preparationProcess.metadata?.fieldEvidenceKeywords as string[] | undefined
  const acceptanceCheckpoints = terminalProcess.metadata?.acceptanceCheckpoints as string[] | undefined
  const serializedItemWork = JSON.stringify(itemWork)

  expect(itemWork.name, `${stableCode} itemWork should be localized`)
    .toBe(expectation.itemWorkName)
  expect(Array.isArray(fieldEvidenceKeywords), `${stableCode} first process should expose fieldEvidenceKeywords`)
    .toBe(true)
  for (const fragment of expectation.fieldEvidenceFragments) {
    expect(
      fieldEvidenceKeywords?.some((keyword) => processNameMatchesFragment(keyword, fragment)),
      `${stableCode} first process evidence should include ${fragment}`,
    ).toBe(true)
  }
  expect(terminalProcess.metadata?.handoverEvidenceType, `${stableCode} terminal handover evidence type`)
    .toBe(expectation.handoverEvidenceType)
  expect(Array.isArray(acceptanceCheckpoints), `${stableCode} terminal process should expose acceptanceCheckpoints`)
    .toBe(true)
  expect(acceptanceCheckpoints, `${stableCode} terminal acceptance checkpoint count`)
    .toHaveLength(7)
  const terminalAcceptanceTexts = [terminalProcess.name, ...(acceptanceCheckpoints ?? [])]
  expect(
    terminalAcceptanceTexts.some((text) => (
      processNameMatchesFragment(text, expectation.acceptanceCoreFragment)
    )),
    `${stableCode} terminal acceptance should include ${expectation.acceptanceCoreFragment}`,
  ).toBe(true)
  for (const fragment of expectation.forbiddenRawFragments) {
    expect(
      serializedItemWork.toLocaleLowerCase().includes(fragment.toLocaleLowerCase()),
      `${stableCode} raw serialized itemWork should not keep old English fragment ${fragment}`,
    ).toBe(false)
  }
}

function expectTerminalEvidenceMetadata(
  templateId: string,
  stableCode: string,
  expectation: {
    expectedProcessCount?: number
    handoverEvidenceType: string
    acceptanceFragments: string[]
  },
) {
  const processChildren = processChildrenFor(templateId, stableCode)
  const terminalProcess = processChildren.at(-1)!
  const acceptanceCheckpoints = terminalProcess.metadata?.acceptanceCheckpoints as string[] | undefined

  if (expectation.expectedProcessCount !== undefined) {
    expect(processChildren.length, `${stableCode} process count should not regress below the schedule-trust baseline`)
      .toBeGreaterThanOrEqual(expectation.expectedProcessCount)
  }
  expect(terminalProcess.metadata?.handoverEvidenceType, `${stableCode} terminal handover evidence type`)
    .toBe(expectation.handoverEvidenceType)
  expect(Array.isArray(acceptanceCheckpoints), `${stableCode} terminal process should expose acceptanceCheckpoints`)
    .toBe(true)
  expect(acceptanceCheckpoints, `${stableCode} terminal acceptance checkpoint count`)
    .toHaveLength(7)
  const terminalAcceptanceTexts = [terminalProcess.name, ...(acceptanceCheckpoints ?? [])]
  for (const fragment of expectation.acceptanceFragments) {
    expect(
      terminalAcceptanceTexts.some((text) => processNameMatchesFragment(text, fragment)),
      `${stableCode} terminal acceptance should include ${fragment}`,
    ).toBe(true)
  }
}

