function standardProcessChildrenFor(stableCode: string) {
  const node = flattenChinaTemplateCatalog().find((item) => item.stableCode === stableCode)
  expect(node, `standard catalog itemWork should exist as ${stableCode}`).toBeTruthy()
  return (node!.children ?? []).filter((child) => child.categoryType === 'process')
}

