function stableCodeRulesForPrefix(prefix: string) {
  return STANDARD_INTERNAL_FLOW_RULE_SEED.filter((rule) => {
    const predecessor = rule.predecessorStableCode ?? ''
    const successor = rule.successorStableCode ?? ''
    return predecessor.startsWith(prefix) || successor.startsWith(prefix)
  })
}

function standardInternalFlowStatsFor(stableCode: string) {
  const processChildren = standardProcessChildrenFor(stableCode)
  const processCodes = new Set(processChildren.map((process) => process.stableCode))
  const stableRules = stableCodeRulesForPrefix(`${stableCode}-P`)
    .filter((rule) => (
      rule.matchMode === 'stable_code'
      && rule.predecessorStableCode
      && rule.successorStableCode
      && processCodes.has(rule.predecessorStableCode)
      && processCodes.has(rule.successorStableCode)
    ))
  const dependencyRules = stableRules.filter((rule) => rule.createsDependency)
  const acceptanceGates = stableRules.filter((rule) => rule.createsDependency && rule.relationKind === 'acceptance_gate')
  const duplicateStableCodePairs = stableRules
    .map((rule) => `${rule.predecessorStableCode}->${rule.successorStableCode}`)
    .filter((pair, index, pairs) => pairs.indexOf(pair) !== index)

  return {
    processChildren,
    stableRules,
    dependencyRules,
    acceptanceGates,
    duplicateStableCodePairs,
  }
}

function durationSeedCodes() {
  return new Set(
    STANDARD_WORK_DURATION_SEED.flatMap((rule) => [rule.stableCode, ...rule.standardWorkCodes])
      .filter(Boolean)
      .map((code) => code.toLowerCase()),
  )
}

function hasDurationSeed(node: ChinaTemplateCatalogNode, codes: Set<string>) {
  return codes.has(node.stableCode.toLowerCase())
}

function isDurationBearingNode(node: ChinaTemplateCatalogNode) {
  return isDurationBearingContributionMode(inferDurationContributionMode({
    name: node.name,
    metadata: node.metadata ?? {},
  }))
}

function scheduleTrustDependencyBaseline(processChildren: ChinaTemplateCatalogNode[], slack: number) {
  const durationBearingCount = processChildren.filter(isDurationBearingNode).length
  return Math.max(0, durationBearingCount - slack)
}

