  it('keeps standard equipment-room electromagnetic shielding bound by stable-code internal flow gates', () => {
    const processCodes = new Set(standardProcessChildrenFor('08-18-09').map((process) => process.stableCode))
    const expectedProcessCodes = Array.from({ length: 10 }, (_, index) => `08-18-09-P${String(index + 1).padStart(2, '0')}`)
    for (const processCode of expectedProcessCodes) {
      expect(processCodes.has(processCode), `${processCode} should exist before checking flow gates`).toBe(true)
    }

    const rules = stableCodeRulesForPrefix('08-18-09-P')
      .filter((rule) => rule.matchMode === 'stable_code')
    const rulesByPair = new Map(
      rules.map((rule) => [`${rule.predecessorStableCode}->${rule.successorStableCode}`, rule]),
    )
    const requiredPairs = [
      ['08-18-09-P01', '08-18-09-P02', 'hard_sequence'],
      ['08-18-09-P02', '08-18-09-P03', 'hard_sequence'],
      ['08-18-09-P03', '08-18-09-P04', 'hard_sequence'],
      ['08-18-09-P03', '08-18-09-P05', 'hard_sequence'],
      ['08-18-09-P04', '08-18-09-P06', 'acceptance_gate'],
      ['08-18-09-P05', '08-18-09-P06', 'acceptance_gate'],
      ['08-18-09-P06', '08-18-09-P07', 'acceptance_gate'],
      ['08-18-09-P07', '08-18-09-P08', 'acceptance_gate'],
      ['08-18-09-P08', '08-18-09-P09', 'acceptance_gate'],
      ['08-18-09-P09', '08-18-09-P10', 'acceptance_gate'],
    ] as const

    expect(rules.length, '08-18-09 should not remain an unbound process list').toBeGreaterThanOrEqual(requiredPairs.length)
    for (const [predecessor, successor, relationKind] of requiredPairs) {
      const rule = rulesByPair.get(`${predecessor}->${successor}`)
      expect(rule, `${predecessor} -> ${successor} should be an explicit stable-code flow`).toBeTruthy()
      expect(rule?.relationKind, `${predecessor} -> ${successor} relation kind`).toBe(relationKind)
      expect(rule?.createsDependency, `${predecessor} -> ${successor} should create a dependency`).toBe(true)
      expect(rule?.dependencyType, `${predecessor} -> ${successor} dependency type`).toBe('FS')
      if (relationKind === 'acceptance_gate') {
        expect(rule?.evidenceCodes, `${predecessor} -> ${successor} shielding acceptance evidence`)
          .toEqual(expect.arrayContaining(['GB50300', 'GB/T12190']))
      }
    }
  })

