  it('keeps standard electrical distribution, busduct, and backup-power chains above skeleton-level internal flow density', () => {
    const electricalDistributionPowerItemCodes = [
      '07-01-01',
      '07-01-02',
      '07-02-01',
      '07-02-02',
      '07-02-03',
      '07-04-01',
      '07-05-01',
      '07-06-01',
      '07-06-02',
      '07-06-03',
      '07-06-04',
    ]

    for (const itemCode of electricalDistributionPowerItemCodes) {
      const processChildren = standardProcessChildrenFor(itemCode)
      const processCodes = new Set(processChildren.map((process) => process.stableCode))
      const stableRules = stableCodeRulesForPrefix(`${itemCode}-P`)
        .filter((rule) => (
          rule.matchMode === 'stable_code'
          && rule.predecessorStableCode
          && rule.successorStableCode
          && processCodes.has(rule.predecessorStableCode)
          && processCodes.has(rule.successorStableCode)
        ))
      const dependencyRules = stableRules.filter((rule) => rule.createsDependency)
      const acceptanceGates = stableRules.filter((rule) => rule.createsDependency && rule.relationKind === 'acceptance_gate')
      const duplicateStableCodePairs = stableRules
        .map((rule) => `${rule.predecessorStableCode}->${rule.successorStableCode}`)
        .filter((pair, index, pairs) => pairs.indexOf(pair) !== index)

      expect(processChildren.length, `${itemCode} process depth`).toBeGreaterThanOrEqual(9)
      expect(stableRules.length, `${itemCode} stable-code internal flow density`)
        .toBeGreaterThanOrEqual(scheduleTrustDependencyBaseline(processChildren, 1))
      expect(dependencyRules.length, `${itemCode} dependency-creating internal flow density`)
        .toBeGreaterThanOrEqual(scheduleTrustDependencyBaseline(processChildren, 2))
      expect(acceptanceGates.length, `${itemCode} acceptance gate count`).toBeGreaterThanOrEqual(3)
      expect(duplicateStableCodePairs, `${itemCode} duplicate stable-code internal flow pairs`).toEqual([])
    }
  })

