  it('keeps generated standard catalog process bodies free of generic fallback labels', () => {
    const genericFallbackLabels = [
      '施工准备与技术交底',
      '自检整改与验收',
      '施工或安装',
      '作业面准备',
      '过程施工',
      '质量自检记录',
    ]

    const offendingProcesses = flattenChinaTemplateCatalog()
      .filter((node) => node.categoryType === 'process')
      .flatMap((node) => {
        const metadataFlags = [
          node.metadata?.processPackLevel === 'generic_fallback' ? 'generic_fallback' : null,
          node.metadata?.specializationStatus === 'needs_enterprise_calibration' ? 'needs_enterprise_calibration' : null,
        ].filter(Boolean)
        const nameFlags = genericFallbackLabels.filter((label) => node.name.includes(label))
        return [...metadataFlags, ...nameFlags].map((flag) => `${node.stableCode}:${flag}:${node.name}`)
      })

    expect(offendingProcesses).toEqual([])
  })

