  it('keeps domain specialty itemWork process bodies distinct outside milestone projection templates', () => {
    const processBodyOwners = new Map<string, string[]>()

    for (const template of DOMAIN_WBS_TEMPLATE_CATALOGS) {
      if (template.templateGroup === 'project_milestone') continue

      for (const node of templateNodes(template.templateId)) {
        if (node.categoryType !== 'item_work') continue

        const processNames = (node.children ?? [])
          .filter((child) => child.categoryType === 'process')
          .map((child) => child.name)
        if (!processNames.length) continue

        const processBodyKey = processNames.join(' / ')
        const owners = processBodyOwners.get(processBodyKey) ?? []
        owners.push(`${template.templateId}:${node.stableCode}:${node.name}`)
        processBodyOwners.set(processBodyKey, owners)
      }
    }

    const duplicateProcessBodies = [...processBodyOwners.values()]
      .filter((owners) => owners.length > 1)

    expect(duplicateProcessBodies).toEqual([])
  })

  it('keeps contextualized specialty chains distinct without repeating context prefixes on every process', () => {
    const noisyContextualizedChains: string[] = []

    for (const template of DOMAIN_WBS_TEMPLATE_CATALOGS) {
      for (const node of templateNodes(template.templateId)) {
        if (node.categoryType !== 'item_work') continue

        const processChildren = (node.children ?? []).filter((child) => child.categoryType === 'process')
        const contextualizedProcesses = processChildren.filter((child) => child.metadata?.contextualizedFromProcessChain)
        if (contextualizedProcesses.length === 0) continue

        const scenarioReviewProcesses = contextualizedProcesses.filter((child) => (
          child.name.startsWith('专项扩展场景条件复核:')
        ))
        const repeatedContextNames = contextualizedProcesses.filter((child) => {
          const context = String(child.metadata?.contextualizedFromProcessChain ?? '')
          return context.length > 0 && child.name.includes(`${context}:`)
        })

        if (scenarioReviewProcesses.length !== 1 || repeatedContextNames.length > 0) {
          noisyContextualizedChains.push([
            `${template.templateId}:${node.stableCode}:${node.name}`,
            `scenarioReviews=${scenarioReviewProcesses.length}`,
            `repeatedContextNames=${repeatedContextNames.map((child) => child.name).join('|')}`,
          ].join(' '))
        }
      }
    }

    expect(noisyContextualizedChains).toEqual([])
  })

