  it('keeps renewable PV, wind, storage, substation, grid, access, and handover chains above skeleton density', () => {
    const requiredFamilies = [
      { code: 'REN-01-01-01', label: 'photovoltaic pile support module and inverter installation' },
      { code: 'REN-01-01-02', label: 'wind turbine foundation tower and nacelle erection' },
      { code: 'REN-02-01-01', label: 'battery energy-storage container and fire-control installation' },
      { code: 'REN-02-01-02', label: 'collector cable trench inverter transformer and grounding' },
      { code: 'REN-02-01-03', label: 'booster substation switchgear relay and SCADA commissioning' },
      { code: 'REN-02-01-04', label: 'grid-connection protection metering and dispatch interface' },
      { code: 'REN-03-01-02', label: 'access road drainage fencing and environmental restoration' },
      { code: 'REN-04-01-01', label: 'PV pile foundation support and torque acceptance' },
      { code: 'REN-04-01-02', label: 'PV module string inverter and DC combiner installation' },
      { code: 'REN-04-01-03', label: 'wind turbine foundation anchor cage and concrete curing' },
      { code: 'REN-04-01-04', label: 'wind tower nacelle blade hoisting and alignment' },
      { code: 'REN-04-01-06', label: 'collector cable trench laying splicing and grounding' },
      { code: 'REN-04-01-07', label: 'booster transformer GIS switchgear and relay commissioning' },
      { code: 'REN-04-01-08', label: 'SCADA AGC AVC metering and dispatch interface' },
      { code: 'REN-04-01-09', label: 'grid connection backfeed protection and performance test' },
      { code: 'REN-04-01-10', label: 'whole-station trial operation defects and production handover' },
    ]

    const nodes = templateNodes('china-renewable-energy-specialty')
    const processStableCodes = new Set(nodes.filter((node) => node.categoryType === 'process').map((node) => node.stableCode))

    for (const family of requiredFamilies) {
      const itemWork = nodes.find((node) => node.stableCode === family.code && node.categoryType === 'item_work')
      expect(itemWork, `${family.label} itemWork should exist as ${family.code}`).toBeTruthy()

      const processChildren = (itemWork!.children ?? []).filter((child) => child.categoryType === 'process')
      const stableRules = stableCodeRulesForPrefix(`${family.code}-P`)
        .filter((rule) => (
          rule.matchMode === 'stable_code'
          && rule.predecessorStableCode
          && rule.successorStableCode
          && processStableCodes.has(rule.predecessorStableCode)
          && processStableCodes.has(rule.successorStableCode)
        ))
      const dependencyRules = stableRules.filter((rule) => rule.createsDependency)
      const acceptanceGates = stableRules.filter((rule) => rule.createsDependency && rule.relationKind === 'acceptance_gate')
      const duplicateStableCodePairs = stableRules
        .map((rule) => `${rule.predecessorStableCode}->${rule.successorStableCode}`)
        .filter((pair, index, pairs) => pairs.indexOf(pair) !== index)

      expect(processChildren.length, `${family.label} process depth`).toBeGreaterThanOrEqual(8)
      expect(stableRules.length, `${family.label} stable-code internal flow density`)
        .toBeGreaterThanOrEqual(scheduleTrustDependencyBaseline(processChildren, 1))
      expect(dependencyRules.length, `${family.label} dependency-creating internal flow density`)
        .toBeGreaterThanOrEqual(scheduleTrustDependencyBaseline(processChildren, 2))
      expect(acceptanceGates.length, `${family.label} acceptance gate count`).toBeGreaterThanOrEqual(3)
      expect(duplicateStableCodePairs, `${family.label} duplicate stable-code internal flow pairs`).toEqual([])
    }
  })

