  it('keeps ultra-high-rise core, mega-structure, vertical logistics, facade, MEP, and refuge chains deeper than broad skeleton packs', () => {
    const requiredFamilies = [
      { code: 'UHR-04-01-01', label: 'core-wall climbing formwork cycle and concrete release' },
      { code: 'UHR-04-01-02', label: 'mega-column steel concrete node and splice acceptance' },
      { code: 'UHR-04-01-03', label: 'outrigger belt truss installation and unloading control' },
      { code: 'UHR-04-01-04', label: 'high-strength concrete pumping pressure and temperature control' },
      { code: 'UHR-04-01-05', label: 'tower crane hoist and construction elevator zoning switch' },
      { code: 'UHR-04-01-06', label: 'curtain-wall zoning unit hoisting and BMU interface' },
      { code: 'UHR-04-01-07', label: 'high-zone pump room riser pressure-staging commissioning' },
      { code: 'UHR-04-01-08', label: 'busduct electrical riser and lightning grounding interface' },
      { code: 'UHR-04-01-09', label: 'refuge-floor fire smoke-control and evacuation linkage' },
      { code: 'UHR-04-01-10', label: 'super-tall integrated commissioning and staged handover' },
    ]

    const nodes = templateNodes('china-ultra-high-rise-specialty')
    const processStableCodes = new Set(nodes.filter((node) => node.categoryType === 'process').map((node) => node.stableCode))

    for (const family of requiredFamilies) {
      const itemWork = nodes.find((node) => node.stableCode === family.code && node.categoryType === 'item_work')
      expect(itemWork, `${family.label} itemWork should exist as ${family.code}`).toBeTruthy()

      const processChildren = (itemWork!.children ?? []).filter((child) => child.categoryType === 'process')
      const durationProcesses = processChildren.filter((child) => (
        child.metadata?.durationContributionMode === 'duration_bearing'
        && child.metadata?.processDepthRole === 'field_duration_work'
      ))
      const internalAcceptanceGates = STANDARD_INTERNAL_FLOW_RULE_SEED.filter((rule) => (
        rule.matchMode === 'stable_code'
        && rule.createsDependency
        && rule.relationKind === 'acceptance_gate'
        && rule.predecessorStableCode?.startsWith(`${family.code}-`)
        && rule.successorStableCode?.startsWith(`${family.code}-`)
        && processStableCodes.has(rule.predecessorStableCode)
        && processStableCodes.has(rule.successorStableCode)
      ))

      expect(processChildren.length, `${family.label} process decomposition`).toBeGreaterThanOrEqual(8)
      expect(durationProcesses.length, `${family.label} duration-bearing field anchors`).toBeGreaterThanOrEqual(4)
      expect(internalAcceptanceGates.length, `${family.label} internal acceptance gates`).toBeGreaterThanOrEqual(2)
    }
  })

