  it('keeps data-center thermal, monitoring, security, testing, and operations chains schedulable', () => {
    const requiredFamilies = [
      { code: 'DTC-04-01-13', label: 'lightning protection and equipotential grounding' },
      { code: 'DTC-04-01-14', label: 'in-row precision cooling' },
      { code: 'DTC-04-01-15', label: 'chilled-water pump and valve train' },
      { code: 'DTC-04-01-16', label: 'cooling tower or dry cooler' },
      { code: 'DTC-04-01-17', label: 'water-leak detection' },
      { code: 'DTC-04-01-19', label: 'BMS interface commissioning' },
      { code: 'DTC-04-01-20', label: 'access-control, video, and visitor security' },
      { code: 'DTC-04-01-21', label: 'perimeter security and guard patrol' },
      { code: 'DTC-04-01-23', label: 'very early smoke detection' },
      { code: 'DTC-04-01-24', label: 'network link certification and labeling' },
      { code: 'DTC-04-01-25', label: 'IT load bank testing' },
      { code: 'DTC-04-01-26', label: 'dual utility transfer drill' },
      { code: 'DTC-04-01-28', label: 'Tier or availability acceptance' },
      { code: 'DTC-04-01-29', label: 'operations takeover and SOP transfer' },
      { code: 'DTC-04-01-30', label: 'spares and emergency tools transfer' },
    ]

    const nodes = templateNodes('china-data-center-specialty')
    const processStableCodes = new Set(nodes.filter((node) => node.categoryType === 'process').map((node) => node.stableCode))

    for (const family of requiredFamilies) {
      const itemWork = nodes.find((node) => node.stableCode === family.code && node.categoryType === 'item_work')
      expect(itemWork, `${family.label} itemWork should exist as ${family.code}`).toBeTruthy()

      const processChildren = (itemWork!.children ?? []).filter((child) => child.categoryType === 'process')
      expect(
        processChildren.length,
        `${family.label} native process decomposition`,
      ).toBeGreaterThanOrEqual(8)

      const durationProcesses = processChildren.filter((child) => (
        child.categoryType === 'process'
        && child.metadata?.durationContributionMode === 'duration_bearing'
        && child.metadata?.processDepthRole === 'field_duration_work'
      ))
      expect(
        durationProcesses.length,
        `${family.label} duration-bearing process depth`,
      ).toBeGreaterThanOrEqual(3)

      const internalAcceptanceGates = STANDARD_INTERNAL_FLOW_RULE_SEED.filter((rule) => (
        rule.matchMode === 'stable_code'
        && rule.createsDependency
        && rule.relationKind === 'acceptance_gate'
        && rule.predecessorStableCode?.startsWith(`${family.code}-`)
        && rule.successorStableCode?.startsWith(`${family.code}-`)
        && processStableCodes.has(rule.predecessorStableCode)
        && processStableCodes.has(rule.successorStableCode)
      ))
      expect(
        internalAcceptanceGates.length,
        `${family.label} internal acceptance gates`,
      ).toBeGreaterThanOrEqual(2)
    }
  })

