  it('keeps data-center perimeter supplemental field work before security trial-run and acceptance', () => {
    const names = processChildrenFor('china-data-center-specialty', 'DTC-04-01-21')
      .map((child) => child.name)
    const trialRunIndex = names.indexOf('安保试运行巡检')
    const acceptanceIndex = names.indexOf('周界安防验收')
    const linkageIndex = names.indexOf('报警联动和夜间补光调试')

    expect(trialRunIndex, 'perimeter security trial-run process should exist').toBeGreaterThanOrEqual(0)
    expect(acceptanceIndex, 'perimeter security acceptance process should exist').toBeGreaterThanOrEqual(0)
    expect(linkageIndex, 'perimeter alarm and night-lighting linkage process should remain stable').toBeGreaterThanOrEqual(0)
    expect(linkageIndex, 'alarm linkage should stay before trial-run').toBeLessThan(trialRunIndex)
    expect(trialRunIndex, 'trial-run should stay before final acceptance').toBeLessThan(acceptanceIndex)

    for (const supplementalName of [
      '周界摄像机探测器安装作业',
      '电子巡更点位安装作业',
      '夜间补光联动测试作业',
    ]) {
      const supplementalIndex = names.indexOf(supplementalName)
      expect(supplementalIndex, `supplemental process ${supplementalName} should exist`).toBeGreaterThanOrEqual(0)
      expect(
        supplementalIndex,
        `supplemental process ${supplementalName} must close before security trial-run`,
      ).toBeLessThan(trialRunIndex)
      expect(
        supplementalIndex,
        `supplemental process ${supplementalName} must close before perimeter security acceptance`,
      ).toBeLessThan(acceptanceIndex)
    }
  })

