  it('keeps stable-code depth gates aligned with reordered supplemental process names', () => {
    const processNameByStableCode = new Map<string, string>()
    for (const template of DOMAIN_WBS_TEMPLATE_CATALOGS) {
      for (const node of flattenNodes(template.divisions)) {
        if (node.categoryType === 'process') {
          processNameByStableCode.set(node.stableCode, node.name)
        }
      }
    }

    const targetPrefixes = [
      'CMP-05-01-13',
      'CMP-05-01-17',
      'INT-02-01-01',
      'IKU-03-01-03',
      'MIC-06-01-07',
    ]
    const targetRules = STANDARD_INTERNAL_FLOW_RULE_SEED.filter((rule) => (
      rule.matchMode === 'stable_code'
      && targetPrefixes.some((prefix) => (
        rule.predecessorStableCode?.startsWith(`${prefix}-`)
        || rule.successorStableCode?.startsWith(`${prefix}-`)
      ))
    ))

    expect(targetRules.length, 'target reordered depth families should keep explicit stable-code gates').toBeGreaterThan(0)

    for (const rule of targetRules) {
      const predecessorName = processNameByStableCode.get(rule.predecessorStableCode ?? '')
      const successorName = processNameByStableCode.get(rule.successorStableCode ?? '')
      if (predecessorName) {
        expect(rule.predecessorName, `${rule.id} predecessor name should match WBS node`).toBe(predecessorName)
      }
      if (successorName) {
        expect(rule.successorName, `${rule.id} successor name should match WBS node`).toBe(successorName)
      }
    }
  })

