  it('keeps MiC packaging and transport monitoring supplements in field logistics order', () => {
    const processChildren = processChildrenFor('china-modular-mic-specialty', 'MIC-06-01-11')
    const indexByName = new Map(processChildren.map((child, index) => [child.name, index]))
    const nameByStableCode = new Map(processChildren.map((child) => [child.stableCode, child.name]))

    const packagingPlan = '\u6a21\u5757\u5305\u88c5\u52a0\u56fa\u65b9\u6848\u786e\u8ba4'
    const centerOfGravityProtection = '\u91cd\u5fc3\u548c\u540a\u70b9\u4fdd\u62a4'
    const rainAndImpactProtection = '\u5305\u88c5\u9632\u96e8\u9632\u78b0\u52a0\u56fa\u4f5c\u4e1a'
    const tiltMonitorInstall = '\u503e\u89d2\u9707\u52a8\u76d1\u6d4b\u5668\u5b89\u88c5\u4f5c\u4e1a'
    const vehicleRouteVerification = '\u8fd0\u8f93\u8f66\u8f86\u548c\u8def\u7ebf\u6838\u9a8c'
    const inTransitTiltMonitoring = '\u8fd0\u8f93\u8fc7\u7a0b\u503e\u89d2\u9707\u52a8\u76d1\u6d4b'
    const arrivalDamageInspection = '\u5230\u573a\u5916\u89c2\u548c\u5305\u88c5\u7834\u635f\u68c0\u67e5'
    const damageIssueRegistration = '\u8fd0\u8f93\u635f\u4f24\u95ee\u9898\u767b\u8bb0'
    const damageRectificationRetest = '\u8fd0\u8f93\u635f\u4f24\u6574\u6539\u590d\u6d4b\u4f5c\u4e1a'

    for (const name of [
      packagingPlan,
      centerOfGravityProtection,
      rainAndImpactProtection,
      tiltMonitorInstall,
      vehicleRouteVerification,
      inTransitTiltMonitoring,
      arrivalDamageInspection,
      damageIssueRegistration,
      damageRectificationRetest,
    ]) {
      expect(indexByName.get(name), `MIC-06-01-11 process should exist: ${name}`).toBeGreaterThanOrEqual(0)
    }

    expect(indexByName.get(packagingPlan)).toBeLessThan(indexByName.get(rainAndImpactProtection)!)
    expect(indexByName.get(centerOfGravityProtection)).toBeLessThan(indexByName.get(rainAndImpactProtection)!)
    expect(indexByName.get(rainAndImpactProtection)).toBeLessThan(indexByName.get(tiltMonitorInstall)!)
    expect(indexByName.get(tiltMonitorInstall)).toBeLessThan(indexByName.get(vehicleRouteVerification)!)
    expect(indexByName.get(vehicleRouteVerification)).toBeLessThan(indexByName.get(inTransitTiltMonitoring)!)
    expect(indexByName.get(inTransitTiltMonitoring)).toBeLessThan(indexByName.get(arrivalDamageInspection)!)
    expect(indexByName.get(arrivalDamageInspection)).toBeLessThan(indexByName.get(damageIssueRegistration)!)
    expect(indexByName.get(damageIssueRegistration)).toBeLessThan(indexByName.get(damageRectificationRetest)!)

    expect(nameByStableCode.get('MIC-06-01-11-P03')).toBe(rainAndImpactProtection)
    expect(nameByStableCode.get('MIC-06-01-11-P04')).toBe(tiltMonitorInstall)
    expect(nameByStableCode.get('MIC-06-01-11-P05')).toBe(vehicleRouteVerification)
    expect(nameByStableCode.get('MIC-06-01-11-P06')).toBe(inTransitTiltMonitoring)
    expect(nameByStableCode.get('MIC-06-01-11-P08')).toBe(damageIssueRegistration)
    expect(nameByStableCode.get('MIC-06-01-11-P09')).toBe(damageRectificationRetest)
  })

