  it('keeps duration-bearing specialty itemWorks grounded by process-level duration seeds', () => {
    const criticalTemplateIds = [
      'china-prefabricated-assembly',
      'china-cleanroom-medical-specialty',
      'china-data-center-specialty',
      'china-industrial-cleanroom-specialty',
      'china-foundation-pit-pile',
      'china-tod-upper-cover-specialty',
      'china-modular-mic-specialty',
      'china-heritage-preservation-specialty',
    ]
    const codes = durationSeedCodes()

    const gaps = criticalTemplateIds.flatMap((templateId) => (
      templateNodes(templateId)
        .filter((node) => node.categoryType === 'item_work' && isDurationBearingNode(node))
        .flatMap((itemWork) => {
          if (hasDurationSeed(itemWork, codes)) return []

          const durationBearingProcesses = (itemWork.children ?? [])
            .filter((child) => child.categoryType === 'process' && isDurationBearingNode(child))
          const coveredProcesses = durationBearingProcesses.filter((child) => hasDurationSeed(child, codes))
          const coverageRatio = durationBearingProcesses.length === 0
            ? 0
            : coveredProcesses.length / durationBearingProcesses.length

          if (durationBearingProcesses.length > 0 && coverageRatio >= 0.8) return []

          return [`${templateId}:${itemWork.stableCode}:${itemWork.name}:processDurationCoverage=${coveredProcesses.length}/${durationBearingProcesses.length}`]
        })
    ))

    expect(gaps).toEqual([])
  })

